Envoy API Gateway / Edge Proxy.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Envoy API Gateway / Edge Proxy", "Envoy API Gateway / Edge Proxy") {
    Component("Listener & TLS Termination Component", "Listener & TLS Termination Component", "C++", "Handles TLS 1.3 termination and WAF filtering for incoming traffic.")
    Component("Auth & Authorization Filter", "Auth & Authorization Filter", "Lua / External", "Validates OAuth2/OIDC JWTs, scopes, and enforces persona-based rate limits.")
    Component("Routing & Load Balancing Engine", "Routing & Load Balancing Engine", "Envoy Proxy Core", "Manages circuit breaking and mTLS to backend services.")
    Component("Telemetry & Audit Emitter", "Telemetry & Audit Emitter", "OpenTelemetry / gRPC", "Streams PII-sanitized OpenTelemetry logs to the centralized SIEM.")
}

Rel("Listener & TLS Termination Component", "Auth & Authorization Filter", "Passes authenticated requests for token and policy validation", "")
Rel("Auth & Authorization Filter", "Routing & Load Balancing Engine", "Forwards authorized requests for upstream routing", "")
Rel("Routing & Load Balancing Engine", "Telemetry & Audit Emitter", "Emits request metrics and sanitized audit logs", "")
@enduml

FHIR Interoperability Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhir_interoperability_service, "FHIR Interoperability Service") {
    Component(fhir_api_controller, "FHIR API Controller", "HAPI FHIR REST Framework, Java", "Handles incoming FHIR API requests and provides validation for payloads.")
    Component(transformation_engine, "Transformation Engine", "Apache Camel, Java", "Transforms validated payloads and performs atomic outbox writes.")
    Component(async_event_dispatcher, "Async Event Dispatcher", "Spring Cloud Stream / Kafka Client", "Publishes outbox events to message brokers.")
}

Rel(fhir_api_controller, transformation_engine, "Validated FHIR payload", "Java interface")

@enduml

Region-local PostgreSQL databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(region_local_postgresql_databases, "Region-local PostgreSQL databases") {
    Component(Primary_Database_Engine, "Primary Database Engine", "PostgreSQL, CNPG operator, Amazon RDS", "Stores operational data, EMR records, and billing details with Row-Level Security (RLS) and automated failover.")
    Component(PgBouncer_Connection_Pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages high connection concurrency from microservices to the PostgreSQL database.")
    Component(Audit_Logging_Engine, "Audit Logging Engine", "pgaudit", "Generates and forwards audit logs to the centralized SIEM.")
}

Rel(PgBouncer_Connection_Pooler, Primary_Database_Engine, "Routes and pools database connections", "")
Rel(Primary_Database_Engine, Audit_Logging_Engine, "Generates audit events", "")
@enduml

AWS S3 / on-prem object storage (WORM).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_s3_on_prem_object_storage_worm, "AWS S3 / on-prem object storage (WORM)") {
    Component(Object_Storage_Engine, "Object Storage Engine", "AWS S3 / MinIO", "Enforces 10-year immutable WORM retention and stores encrypted payloads securely.")
    Component(Storage_Tiering_Scheduler, "Storage Tiering Scheduler", "S3 Lifecycle API", "Enforces lifecycle transitions and automated archival policies.")
}

System_Ext(Centralized_SIEM, "Centralized SIEM", "Centralized SIEM & Observability Platform")

Rel(Storage_Tiering_Scheduler, Object_Storage_Engine, "Enforces lifecycle transitions", "S3 Lifecycle API")
Rel(Object_Storage_Engine, Centralized_SIEM, "Streams audit logs", "Syslog / HTTPS")

@enduml
